84	/**
85	 * Email an invitation. Only OWNER/ADMIN of the org may invite. **No Membership
86	 * is created here** — the invitee creates it themselves via `acceptInvite`.
87	 *
88	 * Deliberately does NOT look the email up in the User table. The old version
89	 * did, and that single query produced two leaks from one action any signed-in
90	 * customer can call: it answered "does an account exist with this address?"
91	 * (enumeration oracle), and on a hit it created a Membership whose row then
92	 * exposed the invitee's internal `userId` on the team page — the input the
93	 * unauthenticated 2FA oracle needed (QA-PRELAUNCH P0-2). We send the mail and
94	 * learn nothing: the same response comes back whether or not the address has an
95	 * account, and the sender finds out only if the person chooses to accept.
96	 */
97	export async function inviteMember(
98	  orgId: string,
99	  email: string,
100	  role: string,
101	): Promise<{ error?: string; ok?: boolean; message?: string }> {
102	  const user = await requireUser();
103	  const invitedEmail = String(email ?? "").trim().toLowerCase();
104	  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
105	    return { error: "Enter a valid email address." };
106	  }
107	  const wantRole = String(role ?? "MEMBER").toUpperCase();
108	  if (!isRole(wantRole) || wantRole === "OWNER") {
109	    // OWNER is assigned only at creation / ownership transfer, never via invite.
110	    return { error: "Choose a role of ADMIN, MEMBER or BILLING." };
111	  }
112	
113	  const actor = await actorMembership(orgId, user.id);
114	  if (!actor || !canAdministerOrg(actor.role)) {
115	    return { error: "You don't have permission to invite members to this organization." };
116	  }
117	
118	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { name: true } });
119	  if (!org) return { error: "Organization not found." };
120	
121	  if (invitedEmail === user.email.toLowerCase()) {
122	    return { error: "You're already a member of this organization." };
123	  }
124	
125	  // Narrow lookup, and the ONLY one allowed here: does this address already have
126	  // a Membership *in this org*? It answers nothing the caller can't already see —
127	  // they administer this org, so the roster and its addresses are theirs to read
128	  // (app/dashboard/team/page.tsx) — and it returns null for a non-member whether
129	  // or not that address has an account, so it is not the enumeration oracle the
130	  // old `db.user.findUnique` was. Saves emailing an invitation that would be a
131	  // no-op on accept.
132	  const alreadyIn = await db.membership.findFirst({
133	    where: { orgId, user: { email: invitedEmail } },
134	    select: { id: true },
135	  });
136	  if (alreadyIn) {
137	    return { error: "That person is already a member of this organization." };
138	  }
139	
140	  // Throttle per inviter. This action sends Nxeon-branded mail to an arbitrary
141	  // address chosen by the caller, so without a cap it is a spam relay and a way
142	  // to bury someone in invitations. Same shape as the login / password-reset
143	  // throttles (lib/rate-limit.ts).
144	  const rl = checkRateLimit(`org-invite:${user.id}`, { max: 10, windowMs: 60 * 60 * 1000 });
145	  if (!rl.ok) {
146	    return {
147	      error: `Too many invitations sent recently. Try again in ${Math.ceil(rl.retryAfterSec / 60)} minute(s).`,
148	    };
149	  }
150	
151	  const token = await signInviteToken({
152	    orgId,
153	    email: invitedEmail,
154	    role: wantRole,
155	    invitedBy: user.id,
156	  });
157	  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
158	  const acceptUrl = `${base}/dashboard/team/accept?token=${encodeURIComponent(token)}`;
159	
160	  const { sendMail, emails } = await import("./mailer");
161	  const tpl = emails.teamInvite({
162	    inviterName: user.name,
163	    teamName: org.name,
164	    acceptUrl,
165	  });
166	  // `template` is passed so the send is categorised in the admin EmailLog viewer
167	  // (same shape as worker/billing.ts:182). No `userId`: we deliberately never
168	  // resolved the address to an account, so there is no id to attribute it to.
169	  const sent = await sendMail({
170	    to: invitedEmail,
171	    subject: tpl.subject,
172	    html: tpl.html,
173	    template: tpl.template,
174	  });
175	  if (!sent) {
176	    // Report the failure instead of claiming the invitation went out. `sendMail`
177	    // returns false (and logs to EmailLog) when SMTP is unconfigured or the send
178	    // throws; a cheerful "Invitation sent." over a dropped email is exactly the
179	    // confidently-wrong surface this codebase keeps getting bitten by.
180	    return { error: "We couldn't send that invitation email. Check mail settings and try again." };
181	  }
182	
183	  await db.auditLog.create({
184	    data: {
185	      userId: user.id,
186	      action: "org.invite_sent",
187	      detail: `${invitedEmail} → ${wantRole}`,
188	    },
189	  });
190	  return {
191	    ok: true,
192	    message: `Invitation emailed to ${invitedEmail}. They join the organization when they accept it — the link expires in ${INVITE_TTL_HOURS} hours.`,
193	  };
194	}
