196	/**
197	 * Accept an invitation. This is the ONLY path that creates a Membership for
198	 * someone other than an org's creator, and it runs as the invitee — clicking
199	 * Accept while signed in as the invited address *is* the consent.
200	 *
201	 * Must be triggered by a deliberate click, never on page load: a mutation that
202	 * fires when the emailed URL is merely opened (or prefetched) would join people
203	 * to organizations without their agreement all over again.
204	 *
205	 * Re-checks at redemption time, because the token carries no server-side state:
206	 * the org still exists, the inviter still administers it, the role is still
207	 * sane, and the token's address matches the signed-in account.
208	 */
209	export async function acceptInvite(
210	  token: string,
211	): Promise<{ error?: string; ok?: boolean; orgName?: string; alreadyMember?: boolean }> {
212	  const user = await requireUser();
213	
214	  const claims = await verifyInviteToken(String(token ?? ""));
215	  if (!claims) {
216	    return {
217	      error: "This invitation link is invalid or has expired. Ask the organization owner to send a new one.",
218	    };
219	  }
220	
221	  // Bound to one address, so a forwarded link can't be redeemed by the recipient.
222	  if (claims.email !== user.email.trim().toLowerCase()) {
223	    return {
224	      error: "This invitation was sent to a different email address. Sign in as that account to accept it.",
225	    };
226	  }
227	
228	  if (!isRole(claims.role) || claims.role === "OWNER") {
229	    return { error: "This invitation carries an invalid role and can't be accepted." };
230	  }
231	
232	  const org = await db.organization.findUnique({
233	    where: { id: claims.orgId },
234	    select: { id: true, name: true },
235	  });
236	  if (!org) return { error: "That organization no longer exists." };
237	
238	  // Revocation, given there is no invitation row to delete: an outstanding
239	  // invitation dies the moment its sender loses the right to have sent it.
240	  const inviter = await actorMembership(org.id, claims.invitedBy);
241	  if (!inviter || !canAdministerOrg(inviter.role)) {
242	    return {
243	      error: "Whoever invited you no longer administers this organization, so the invitation is no longer valid.",
244	    };
245	  }
246	
247	  const existing = await actorMembership(org.id, user.id);
248	  if (existing) {
249	    return { ok: true, orgName: org.name, alreadyMember: true };
250	  }
251	
252	  await db.membership.create({
253	    data: { orgId: org.id, userId: user.id, role: claims.role },
254	  });
255	  await db.auditLog.create({
256	    data: {
257	      userId: user.id,
258	      action: "org.invite_accepted",
259	      detail: `${org.name} → ${claims.role}`,
260	    },
261	  });
262	  revalidatePath("/dashboard/team");
263	  return { ok: true, orgName: org.name };
264	}
