374	/**
375	 * Team invitations: consent tokens, plus who is entitled to see whom.
376	 *
377	 * WHY THIS MODULE NO LONGER EXPORTS `requireArea`
378	 * ----------------------------------------------
379	 * It used to export `requireArea(orgId, area)` — a page guard for "org-scoped
380	 * dashboard pages". There were none: `requireArea` had zero call sites in the
381	 * repo (AUDIT-24H rec. 47, QA-PRELAUNCH P1-19), `memberCanAccessHref` was
382	 * referenced only from its own docblock, and `Membership.areas` was write-only.
383	 * Meanwhile the Team UI rendered a checkbox per dashboard area and reported
384	 * "Access updated." So an owner who unticked everything except Invoices was
385	 * shown a restriction that no loader, action or route ever consulted. That is
386	 * the same defect class as the fake SSL certs and the migration that logged 4/4
387	 * with six domains dark, and it is the more dangerous shape of it: a security
388	 * control that reports success while enforcing nothing.
389	 *
390	 * Wiring it up for real would mean org-scoping every dashboard loader and every
391	 * server action that touches a server, domain, volume, invoice or ticket — none
392	 * of which live in this module's blast radius. A half-wired version (nav hidden,
393	 * loaders open) is strictly worse than none, because hiding a nav item looks
394	 * like enforcement. So the area system is deleted rather than faked, and this
395	 * module now carries the two things teams genuinely need in order to be safe.
396	 *
397	 * 1. INVITE TOKENS (consent). `inviteMember` used to create a Membership
398	 *    outright — the invitee never agreed to anything — and the team page then
399	 *    handed the inviter every co-member's `userId` and email. That is precisely
400	 *    the identity feed that made the unauthenticated 2FA oracle
401	 *    (`verifyTotpForUser`, QA-PRELAUNCH P0-2) targetable at a named account:
402	 *    type a victim's email, get back their internal id. Membership now requires
403	 *    the invitee to click Accept while signed in as the invited address.
404	 *
405	 * 2. `canAdministerOrg` — the single definition of "may administer membership",
406	 *    used both to authorise mutations and to decide whether a viewer is
407	 *    entitled to co-members' email addresses.
408	 *
409	 * Plain server-side module (no "use server"), so both the server actions and the
410	 * accept page can import these helpers. Nothing here is client-safe.
411	 */
412	import { createHash } from "node:crypto";
413	import { EncryptJWT, jwtDecrypt } from "jose";
414	
415	/**
416	 * Invitation lifetime. Short on purpose: the token is the entire invitation
417	 * (see below), so expiry is the only thing that eventually retires a link the
418	 * sender regrets.
419	 */
420	export const INVITE_TTL_HOURS = 72;
421	
422	/** What an invitation carries. `invitedBy` is re-checked at accept time. */
423	export type InviteClaims = {
424	  orgId: string;
425	  /** Lowercased email the invitation was addressed to. Binds the link to one person. */
426	  email: string;
427	  role: string;
428	  invitedBy: string;
429	};
430	
431	/**
432	 * 256-bit key for the invite JWE, derived from AUTH_SECRET with an
433	 * invite-specific salt — the same derivation pattern as lib/terminal-token.ts.
434	 * The distinct salt means a session cookie can never be replayed as an
435	 * invitation (or vice-versa) even though both trace back to one secret.
436	 */
437	function inviteKey(): Uint8Array {
438	  const secret = process.env.AUTH_SECRET;
439	  if (!secret) throw new Error("AUTH_SECRET is not set — cannot issue team invitations");
440	  return new Uint8Array(createHash("sha256").update(`nxeon-org-invite:${secret}`).digest());
441	}
442	
443	/**
444	 * Mint an invitation token.
445	 *
446	 * ENCRYPTED (JWE, A256GCM), not merely signed. A signed JWT's payload is
447	 * readable by anyone holding the link, and this payload contains the inviter's
448	 * `userId` — the exact value the 2FA oracle needed (P0-2). An invitation that
449	 * leaked an internal user id to whoever opened the email would reintroduce the
450	 * hole this change exists to close, so the token is opaque to its bearer.
451	 *
452	 * STATELESS by necessity: prisma/schema.prisma has no Invitation model and is
453	 * frozen for this change. The consequences are real and are stated plainly in
454	 * the UI rather than papered over — pending invitations cannot be listed, and
455	 * they cannot be revoked individually. What limits them instead:
456	 *   - they expire (INVITE_TTL_HOURS);
457	 *   - `acceptInvite` re-verifies that the inviter STILL holds OWNER/ADMIN in the
458	 *     org, so demoting or removing an admin voids their outstanding invitations;
459	 *   - they are bound to one email address, so a forwarded link is useless.
460	 * If pending-invite listing/revocation is wanted, that needs a schema field —
461	 * an `Invitation` model (orgId, email, role, invitedById, tokenHash, expiresAt,
462	 * acceptedAt, revokedAt) is the missing piece.
463	 */
464	export async function signInviteToken(claims: InviteClaims): Promise<string> {
465	  return new EncryptJWT({
466	    // `kind` is belt-and-braces on top of the salted key: any token that decrypts
467	    // but wasn't minted here is rejected rather than interpreted.
468	    kind: "org-invite",
469	    orgId: claims.orgId,
470	    email: claims.email,
471	    role: claims.role,
472	    invitedBy: claims.invitedBy,
473	  })
474	    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
475	    .setIssuedAt()
476	    .setExpirationTime(`${INVITE_TTL_HOURS}h`)
477	    .encrypt(inviteKey());
478	}
479	
480	/**
481	 * Decrypt + validate an invitation token. Returns null for anything that isn't a
482	 * well-formed, unexpired invitation — tampered, truncated, expired, minted with
483	 * a different secret, or a token of some other kind. Never throws, so callers
484	 * can render one honest "invalid or expired" message without leaking which of
485	 * those it was.
486	 */
487	export async function verifyInviteToken(token: string): Promise<InviteClaims | null> {
488	  if (!token) return null;
489	  try {
490	    const { payload } = await jwtDecrypt(token, inviteKey());
491	    if (payload.kind !== "org-invite") return null;
492	    const { orgId, email, role, invitedBy } = payload as Record<string, unknown>;
493	    if (
494	      typeof orgId !== "string" ||
495	      typeof email !== "string" ||
496	      typeof role !== "string" ||
497	      typeof invitedBy !== "string" ||
498	      !orgId ||
499	      !email ||
500	      !role ||
501	      !invitedBy
502	    ) {
503	      return null;
504	    }
505	    return { orgId, email: email.toLowerCase(), role, invitedBy };
506	  } catch {
507	    return null;
508	  }
509	}
