"use client";

import { useEffect } from "react";

/**
 * Invisible helper on the register page. If the visitor arrived via a referral
 * link (?ref=CODE), it stashes the code in a cookie so the `register` server
 * action can attribute the signup. Reads window.location directly to avoid a
 * Suspense boundary requirement.
 */
export function ReferralCapture() {
  useEffect(() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const ref = params.get("ref");
      if (!ref) return;
      const code = ref.trim().toUpperCase().slice(0, 32);
      if (!/^[A-Z0-9_-]+$/.test(code)) return;
      // 30-day cookie, readable by the server action.
      document.cookie = `nxeon_ref=${encodeURIComponent(code)}; path=/; max-age=${60 * 60 * 24 * 30}; SameSite=Lax`;
    } catch {
      /* non-fatal */
    }
  }, []);
  return null;
}
"use client";

import { useEffect } from "react";

/**
 * Invisible helper mounted on every dashboard page. If the visitor arrived via a
 * partner deep link (?ref=kodely — from /api/partner/checkout), it stashes the
 * partner id in a cookie so payAndDeploy / purchaseDomain can tag the resulting
 * order with `partnerSource`, WITHOUT threading a query param through every
 * intermediate wizard step and redirect. Mirrors ReferralCapture's pattern.
 *
 * 24h TTL: this is "attribute the order placed in this session", not a durable
 * referral — much shorter-lived than the 30-day referral cookie.
 */
const KNOWN_PARTNERS = ["kodely"];

export function PartnerSourceCapture() {
  useEffect(() => {
    try {
      const params = new URLSearchParams(window.location.search);
      const ref = params.get("ref");
      if (!ref) return;
      const id = ref.trim().toLowerCase().slice(0, 32);
      if (!KNOWN_PARTNERS.includes(id)) return;
      document.cookie = `nx_partner_ref=${encodeURIComponent(id)}; path=/; max-age=${60 * 60 * 24}; SameSite=Lax`;
    } catch {
      /* non-fatal */
    }
  }, []);
  return null;
}
// Plain (non-"use server") module for the growth engine: constants, env getters
// and pure helpers shared by server actions and pages. Safe to import from any
// server module. Do NOT import this from client components — it pulls in `crypto`.

import { randomInt } from "crypto";
import type { CouponKind } from "@prisma/client";

/**
 * Reward (in cents) granted to BOTH the referrer and the referred user when the
 * referred user completes their first successful paid action. Env override:
 * REFERRAL_REWARD_CENTS. Defaults to 500 ($5.00).
 */
export function referralRewardCents(): number {
  const n = Number(process.env.REFERRAL_REWARD_CENTS);
  return Number.isFinite(n) && n >= 0 ? Math.round(n) : 500;
}

/**
 * Free wallet credit (in cents) granted on signup. Env override:
 * SIGNUP_FREE_CREDIT_CENTS. Defaults to 0 (feature off).
 */
export function signupFreeCreditCents(): number {
  const n = Number(process.env.SIGNUP_FREE_CREDIT_CENTS);
  return Number.isFinite(n) && n >= 0 ? Math.round(n) : 0;
}

// Unambiguous alphabet (no 0/O/1/I/L) for human-shareable referral codes.
const CODE_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";

/** Generate a random, unambiguous referral code (uppercase). Uniqueness must be
 *  enforced by the caller against the DB. */
export function generateReferralCode(length = 7): string {
  let out = "";
  for (let i = 0; i < length; i++) out += CODE_ALPHABET[randomInt(CODE_ALPHABET.length)];
  return out;
}

/** Result of validating a promo code for a top-up (see applyCouponToTopup). */
export type CouponApplyResult =
  | {
      ok: true;
      couponId: string;
      code: string;
      /** Extra wallet credit (in cents) the user receives on top of the amount added. */
      bonusCents: number;
      /** Human-readable summary, e.g. "20% bonus". */
      label: string;
    }
  | { ok: false; error: string };

/** Human-readable summary of what a coupon grants, e.g. "20% bonus", "$5.00 credit". */
export function describeCoupon(coupon: { kind: CouponKind; value: number }): string {
  switch (coupon.kind) {
    case "PERCENT":
      return `${coupon.value}% bonus`;
    case "FIXED_CENTS":
      return `$${(coupon.value / 100).toFixed(2)} off`;
    case "CREDIT_CENTS":
      return `$${(coupon.value / 100).toFixed(2)} credit`;
    default:
      return "discount";
  }
}

