"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { requireArea } from "./rbac";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { getSettingBool } from "./settings";
import {
  MIN_PAYOUT_CENTS,
  PAYOUT_STATUSES,
  REFERRAL_EARNING_DESCRIPTION,
  type PayoutStatus,
} from "./affiliate";
import { emailVerificationError } from "./email-verification";

/** Local sentinel: requested payout exceeds the caller's cashable affiliate balance. */
class PayoutExceedsAvailableError extends Error {
  availableCents: number;
  constructor(availableCents: number) {
    super("PAYOUT_EXCEEDS_AVAILABLE");
    this.name = "PayoutExceedsAvailableError";
    this.availableCents = availableCents;
  }
}

// ---------- Customer: request a payout ----------

/**
 * Request an affiliate payout for `amountCents`. Model: referral rewards already
 * live in the wallet, so a payout CONVERTS wallet credit into a cash-out request —
 * it DEBITS the wallet now and records a PENDING AffiliatePayout (admin later marks
 * PAID; a DECLINE credits the wallet back). Guards:
 *  - integer cents ≥ MIN_PAYOUT_CENTS ($25)
 *  - amount ≤ the caller's cashable affiliate balance (unclaimed referral
 *    commission, capped by the actual wallet balance), re-read INSIDE the
 *    transaction so two concurrent requests can't both pass a stale check.
 *  - the wallet debit is an atomic guarded updateMany, so even a race can never
 *    drive the balance negative — the second request fails cleanly.
 */
export async function requestAffiliatePayout(
  amountCents: number
): Promise<{ ok?: boolean; error?: string }> {
  // Money path, and the sharpest one in the product: this converts a customer's
  // wallet balance into a CASH-OUT request that a member of staff then marks
  // PAID. An admin impersonating a customer could open the request and approve
  // it themselves, so the whole loop — request and approval — would sit with one
  // person and never involve the account holder at all. `adminUpdatePayout`
  // below is deliberately staff-gated for the second half; this is the first.
  await assertNotImpersonating();
  const user = await requireUser();
  // Purchase gate: an unverified address means we cannot reach the person we
  // are about to charge. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  // Feature flag: the referral/affiliate program can be switched off platform-wide.
  if (!(await getSettingBool("feature_referrals", true))) {
    return { error: "The affiliate program is currently unavailable." };
  }

  const cents = Math.round(Number(amountCents));
  if (!Number.isFinite(cents) || cents <= 0) {
    return { error: "Enter a valid amount." };
  }
  if (cents < MIN_PAYOUT_CENTS) {
    return { error: `Minimum payout is $${(MIN_PAYOUT_CENTS / 100).toFixed(2)}.` };
  }

  try {
    await db.$transaction(async (tx) => {
      // Re-read all state inside the tx to serialize concurrent requests.
      const [account, earnedAgg, payouts] = await Promise.all([
        tx.user.findUnique({ where: { id: user.id }, select: { balanceCents: true } }),
        tx.walletTransaction.aggregate({
          _sum: { amountCents: true },
          where: { userId: user.id, description: REFERRAL_EARNING_DESCRIPTION },
        }),
        tx.affiliatePayout.findMany({
          where: { userId: user.id, status: { not: "DECLINED" } },
          select: { amountCents: true },
        }),
      ]);
      const walletBalanceCents = account?.balanceCents ?? 0;
      const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
      const claimedCents = payouts.reduce((s, p) => s + p.amountCents, 0);
      const availableCents = Math.max(
        0,
        Math.min(walletBalanceCents, totalEarnedCents - claimedCents)
      );
      if (cents > availableCents) throw new PayoutExceedsAvailableError(availableCents);

      // Atomic guarded debit — hard-stops any residual race from overdrawing.
      await debitWallet(tx, user.id, cents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -cents,
          description: "Affiliate payout request (wallet cash-out)",
        },
      });
      await tx.affiliatePayout.create({
        data: { userId: user.id, amountCents: cents, status: "PENDING" },
      });
      await tx.auditLog.create({
        data: {
          userId: user.id,
          action: "affiliate.payout_request",
          detail: `$${(cents / 100).toFixed(2)}`,
        },
      });
    });
  } catch (e) {
    if (e instanceof PayoutExceedsAvailableError) {
      return { error: `You only have $${(e.availableCents / 100).toFixed(2)} available to withdraw.` };
    }
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient wallet balance for this payout." };
    }
    throw e;
  }

  revalidatePath("/dashboard/affiliate");
  return { ok: true };
}

// ---------- Admin: update a payout's status ----------

const ALLOWED: readonly PayoutStatus[] = PAYOUT_STATUSES;

/**
 * Move a payout request to APPROVED / PAID / DECLINED. Money already left the
 * wallet when the request was created, so:
 *   - PAID     : just stamp `paidAt` (no wallet change — cash was already reserved).
 *   - DECLINED : credit the reserved amount back to the wallet (cash-out cancelled).
 *   - reactivating a DECLINED payout (back to PENDING/APPROVED/PAID): re-debit it,
 *     guarded, so a declined-then-reinstated payout can't be double-spent.
 * Billing-area gated. The status change + wallet move are one transaction.
 */
export async function adminUpdatePayout(
  id: string,
  status: string
): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireArea("billing");

  if (!ALLOWED.includes(status as PayoutStatus)) {
    return { error: "Invalid status." };
  }
  const payout = await db.affiliatePayout.findUnique({ where: { id } });
  if (!payout) return { error: "Payout not found." };

  const wasDeclined = payout.status === "DECLINED";
  const willDecline = status === "DECLINED";

  try {
    await db.$transaction(async (tx) => {
      await tx.affiliatePayout.update({
        where: { id },
        data: {
          status,
          paidAt: status === "PAID" ? new Date() : null,
        },
      });
      if (willDecline && !wasDeclined) {
        // Cancel the cash-out: return the reserved funds to the wallet.
        await tx.user.update({
          where: { id: payout.userId },
          data: { balanceCents: { increment: payout.amountCents } },
        });
        await tx.walletTransaction.create({
          data: {
            userId: payout.userId,
            amountCents: payout.amountCents,
            description: "Affiliate payout declined (funds returned)",
          },
        });
      } else if (!willDecline && wasDeclined) {
        // Reinstating a previously-declined payout: re-reserve the funds (guarded).
        await debitWallet(tx, payout.userId, payout.amountCents);
        await tx.walletTransaction.create({
          data: {
            userId: payout.userId,
            amountCents: -payout.amountCents,
            description: "Affiliate payout reinstated (wallet cash-out)",
          },
        });
      }
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Customer's wallet no longer covers this payout — cannot reinstate." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "affiliate.payout_update",
      detail: `${payout.id} → ${status} ($${(payout.amountCents / 100).toFixed(2)})`,
    },
  });

  revalidatePath("/admin/affiliate");
  return { ok: true };
}
// Affiliate program logic — tier constants + earnings/payout computation.
//
// Plain (non-"use server") module: exports constants and (db-backed) computation
// helpers used by the affiliate pages and server actions. Not for client import.
//
// Accounting model (revised — fixes the affiliate double-pay)
// -----------------------------------------------------------
// The existing referral engine (lib/actions-growth.ts → maybeRewardReferral)
// already credits a referrer's WALLET when a person they referred makes their
// first payment, writing a ledger row with the description below. Because that
// money is ALREADY spendable in the wallet, an affiliate "payout" must not mint
// new money — it CONVERTS existing wallet credit into a cash-out request:
//
//   * request payout  -> DEBIT the wallet now, create AffiliatePayout(PENDING)
//   * admin PAID       -> just mark paid (the money already left the wallet)
//   * admin DECLINED   -> CREDIT the wallet back (cash-out cancelled)
//
// `totalEarned` (the referral ledger sum) stays the lifetime-commission headline,
// but "available to cash out" is now capped by the ACTUAL wallet balance so a
// customer can't both spend their referral credit on servers AND cash it out
// (the old bug: earnings were counted as separately cashable on top of the wallet).
//
// available = clamp(0, min(walletBalance, totalEarned − PENDING − APPROVED − PAID))

import { db } from "./db";

/** Exact WalletTransaction.description written for the referrer's reward (see
 *  lib/actions-growth.ts). Used to total affiliate earnings from the ledger. */
export const REFERRAL_EARNING_DESCRIPTION = "Referral bonus — you referred a friend";

/** Minimum balance (cents) a customer must have available to request a payout. */
export const MIN_PAYOUT_CENTS = 2500; // $25.00

/** Payout lifecycle statuses (mirrors AffiliatePayout.status). */
export const PAYOUT_STATUSES = ["PENDING", "APPROVED", "PAID", "DECLINED"] as const;
export type PayoutStatus = (typeof PAYOUT_STATUSES)[number];

/**
 * Commission tiers. `perReferralCents` is what the marketing copy advertises a
 * paying referral is worth once you reach `minReferrals` paying referrals — an
 * escalating incentive. (The wallet credit actually paid per referral is governed
 * by the `referral_reward_cents` Setting / REFERRAL_REWARD_CENTS in the growth
 * engine; these tiers are the customer-facing program description.)
 */
export const AFFILIATE_TIERS = [
  { name: "Starter", minReferrals: 0, perReferralCents: 500 },
  { name: "Pro", minReferrals: 5, perReferralCents: 800 },
  { name: "Elite", minReferrals: 15, perReferralCents: 1200 },
] as const;

export type AffiliateTier = (typeof AFFILIATE_TIERS)[number];

/** The tier a customer currently sits in given their paying-referral count. */
export function currentTier(payingReferrals: number): AffiliateTier {
  let tier: AffiliateTier = AFFILIATE_TIERS[0];
  for (const t of AFFILIATE_TIERS) {
    if (payingReferrals >= t.minReferrals) tier = t;
  }
  return tier;
}

/** The next tier up (null if already at the top), for "N more to unlock…" copy. */
export function nextTier(payingReferrals: number): AffiliateTier | null {
  return AFFILIATE_TIERS.find((t) => t.minReferrals > payingReferrals) ?? null;
}

export type AffiliateEarnings = {
  referredCount: number;
  payingCount: number;
  totalEarnedCents: number;
  pendingPayoutCents: number; // PENDING + APPROVED (in-flight, not yet cashed out)
  paidPayoutCents: number; // PAID
  availableCents: number; // totalEarned − (pending + approved + paid)
  tier: AffiliateTier;
  next: AffiliateTier | null;
  canRequestPayout: boolean;
};

/**
 * Compute a customer's affiliate standing: referral counts, lifetime earnings
 * (from the wallet ledger) and how much is still available to cash out after
 * subtracting non-declined payouts.
 */
export async function computeAffiliateEarnings(userId: string): Promise<AffiliateEarnings> {
  const [referredCount, payingCount, earnedAgg, payouts, account] = await Promise.all([
    db.user.count({ where: { referredById: userId } }),
    db.user.count({ where: { referredById: userId, referralRewardedAt: { not: null } } }),
    db.walletTransaction.aggregate({
      _sum: { amountCents: true },
      where: { userId, description: REFERRAL_EARNING_DESCRIPTION },
    }),
    db.affiliatePayout.findMany({
      where: { userId, status: { not: "DECLINED" } },
      select: { amountCents: true, status: true },
    }),
    db.user.findUnique({ where: { id: userId }, select: { balanceCents: true } }),
  ]);

  const totalEarnedCents = earnedAgg._sum.amountCents ?? 0;
  const walletBalanceCents = account?.balanceCents ?? 0;
  let pendingPayoutCents = 0;
  let paidPayoutCents = 0;
  for (const p of payouts) {
    if (p.status === "PAID") paidPayoutCents += p.amountCents;
    else pendingPayoutCents += p.amountCents; // PENDING or APPROVED
  }

  // Referral credit already sits in the wallet; a payout debits the wallet. So the
  // cashable amount is the unclaimed referral commission, but never more than the
  // customer actually still holds in their wallet (they may have spent some of it).
  const unclaimedEarnedCents = Math.max(0, totalEarnedCents - pendingPayoutCents - paidPayoutCents);
  const availableCents = Math.max(0, Math.min(walletBalanceCents, unclaimedEarnedCents));

  return {
    referredCount,
    payingCount,
    totalEarnedCents,
    pendingPayoutCents,
    paidPayoutCents,
    availableCents,
    tier: currentTier(payingCount),
    next: nextTier(payingCount),
    canRequestPayout: availableCents >= MIN_PAYOUT_CENTS,
  };
}

