              {commissions.map((c) => (
                <tr key={c.id}>
                  <td className="text-xs text-slate-400" title={c.createdAt.toISOString()}>
                    {timeAgo(c.createdAt)}
                  </td>
                  <td className="text-xs text-slate-400">{c.customer.name || c.customer.email}</td>
                  <td>
                    <Badge tone={KIND_TONE[c.kind] ?? "slate"}>{c.kind.toLowerCase()}</Badge>
                  </td>
                  <td className="text-right font-mono">{formatMoney(c.amountCents, currency)}</td>
                  <td>
                    <Badge tone={c.status === "PAID" ? "green" : c.status === "VOID" ? "slate" : "amber"}>
                      {c.status.toLowerCase()}
                    </Badge>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
import { createHmac, timingSafeEqual } from "node:crypto";
import type { cookies } from "next/headers";
import { getSetting } from "@/lib/settings";

/**
 * Partner API + SSO foundation. Lets a trusted first-party client (Kodely) act on
 * behalf of a linked Nxeon account: one identity, one wallet, Nxeon does the
 * provisioning/billing. Two trust mechanisms:
 *
 *  1. Server-to-server API key (`X-Api-Key`) — for Kodely's backend → Nxeon calls.
 *  2. Signed SSO codes — a short-lived, HMAC-signed authorization code minted by
 *     Nxeon's /sso/authorize (after the user logs in) and exchanged by Kodely's
 *     backend for the linked Nxeon identity. Stateless (no DB), like the existing
 *     marketing-unsub token, keyed by AUTH_SECRET.
 */

function secret(): string {
  const s = process.env.AUTH_SECRET;
  if (!s) throw new Error("AUTH_SECRET is not set — cannot sign partner tokens");
  return s;
}

// ---- Partner API key (server-to-server) -----------------------------------

/** The shared secret Kodely's backend sends as `X-Api-Key`. Set in Settings. */
export async function partnerApiKey(): Promise<string> {
  return (await getSetting("kodely_partner_api_key", "")).trim();
}

/** Constant-time check of an incoming `X-Api-Key` against the configured key. */
export async function verifyPartnerKey(presented: string | null | undefined): Promise<boolean> {
  const expected = await partnerApiKey();
  if (!expected || !presented) return false;
  const a = Buffer.from(presented);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}

/** Gate a partner route. Returns true if the request carries a valid key. */
export async function isPartnerRequest(req: Request): Promise<boolean> {
  return verifyPartnerKey(req.headers.get("x-api-key"));
}

// ---- SSO authorization codes (browser handshake) --------------------------

const SSO_TTL_MS = 5 * 60_000; // codes are single-use-window, 5 minutes

type SsoPayload = { u: string; c: string; r: string; e: number };

function b64urlJson(obj: unknown): string {
  return Buffer.from(JSON.stringify(obj)).toString("base64url");
}

function ssoSig(payloadB64: string): string {
  return createHmac("sha256", secret()).update(`sso:${payloadB64}`).digest("base64url");
}

/** Mint a signed code binding an Nxeon userId to a client + redirect_uri, 5-min TTL. */
export function mintSsoCode(userId: string, clientId: string, redirectUri: string): string {
  const payloadB64 = b64urlJson({ u: userId, c: clientId, r: redirectUri, e: Date.now() + SSO_TTL_MS } satisfies SsoPayload);
  return `${payloadB64}.${ssoSig(payloadB64)}`;
}

/** Verify a code for a given client + redirect_uri. Returns the Nxeon userId or null. */
export function verifySsoCode(code: string | null | undefined, clientId: string, redirectUri: string): string | null {
  if (!code || !code.includes(".")) return null;
  const [payloadB64, sig] = code.split(".", 2);
  let expected: string;
  try {
    expected = ssoSig(payloadB64);
  } catch {
    return null;
  }
  const a = Buffer.from(sig);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  let p: SsoPayload;
  try {
    p = JSON.parse(Buffer.from(payloadB64, "base64url").toString());
  } catch {
    return null;
  }
  if (p.c !== clientId || p.r !== redirectUri) return null;
  if (typeof p.e !== "number" || Date.now() > p.e) return null;
  return p.u || null;
}

// ---- Redirect-URI allowlist (prevents open redirect) ----------------------

/**
 * Allowed redirect_uri prefixes for the Kodely SSO client, comma-separated in the
 * `kodely_sso_redirects` Setting (e.g. "https://kodely.site,https://app.kodely.site").
 * A redirect_uri must start with one of these, over HTTPS.
 */
export async function isAllowedRedirect(redirectUri: string): Promise<boolean> {
  if (!/^https:\/\//i.test(redirectUri)) return false;
  const raw = (await getSetting("kodely_sso_redirects", "")).trim();
  if (!raw) return false;
  const allowed = raw.split(",").map((s) => s.trim().replace(/\/$/, "")).filter(Boolean);
  return allowed.some((a) => redirectUri === a || redirectUri.startsWith(a + "/") || redirectUri.startsWith(a + "?"));
}

// ---- Outbound webhook to the partner (status callbacks) --------------------

/**
 * Notify the partner (Kodely) of an async event (provision done, SSL live, …).
 * Best-effort, HMAC-signed with a DEDICATED webhook secret (`kodely_webhook_secret`)
 * — deliberately NOT AUTH_SECRET, which also signs every Nxeon session JWT and must
 * never leave this server; Kodely needs the signing key to verify the webhook, so it
 * has to be an independent, revocable secret of its own. No-op until both
 * `kodely_webhook_url` and `kodely_webhook_secret` are set.
 */
export async function notifyPartner(event: string, payload: Record<string, unknown>): Promise<void> {
  try {
    const url = (await getSetting("kodely_webhook_url", "")).trim();
    const whSecret = (await getSetting("kodely_webhook_secret", "")).trim();
    if (!url || !whSecret) return;
    const body = JSON.stringify({ event, payload, at: Date.now() });
    const sig = createHmac("sha256", whSecret).update(body).digest("base64url");
    await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json", "x-nxeon-signature": sig },
      body,
    });
  } catch {
    /* best-effort — a failed webhook must never break provisioning */
  }
}

// ---- Order attribution (which orders came from a partner deep link) -------

/** Known partner ids allowed to tag an order via ?ref= — anything else is dropped. */
export const PARTNER_IDS = ["kodely"] as const;
export type PartnerId = (typeof PARTNER_IDS)[number];

export const PARTNER_SOURCE_COOKIE = "nx_partner_ref";

/**
 * Read the partner-source cookie set by PartnerSourceCapture (a ?ref=kodely deep
 * link into /dashboard/deploy or /dashboard/domains). Used at ORDER-CREATION time
 * (payAndDeploy, purchaseDomain) to tag the Server/Domain row with `partnerSource`,
 * so the provision-success webhook (worker/index.ts, purchaseDomain) knows which
 * orders to notify the partner about — most orders are direct Nxeon customers and
 * must NEVER be forwarded to Kodely's webhook.
 */
export function partnerSourceFromCookie(jar: Awaited<ReturnType<typeof cookies>>): PartnerId | undefined {
  const v = jar.get(PARTNER_SOURCE_COOKIE)?.value;
  return (PARTNER_IDS as readonly string[]).includes(v ?? "") ? (v as PartnerId) : undefined;
}
"use server";

// Admin server actions for the KOL / Agency partner program: create & manage
// partners and their commission rates, attach/detach customers, and settle
// accrued commission (mark PAID). Billing-area gated, mirroring the existing
// affiliate admin actions in lib/actions-affiliate.ts.

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireArea } from "./rbac";

/** Normalise a partner code: uppercase, alphanumerics/dash, trimmed. */
function normalizeCode(raw: string): string {
  return raw
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9-]/g, "")
    .slice(0, 32);
}

/** Clamp a percent to a sane 0–90 range (integer-ish, 2dp). */
function clampRate(raw: number): number {
  if (!Number.isFinite(raw)) return 0;
  return Math.min(90, Math.max(0, Math.round(raw * 100) / 100));
}

// ---------- Create a partner ----------

export async function adminCreatePartner(
  _prev: unknown,
  formData: FormData
): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("billing");

  const name = String(formData.get("name") ?? "").trim();
  const code = normalizeCode(String(formData.get("code") ?? ""));
  const contactEmail = String(formData.get("contactEmail") ?? "").trim() || null;
  const rate = clampRate(Number(formData.get("commissionRatePct")));

  if (!name) return { error: "Partner name is required." };
  if (code.length < 3) return { error: "Code must be at least 3 characters (A–Z, 0–9, dash)." };
  if (rate <= 0) return { error: "Commission rate must be greater than 0%." };

  const clash = await db.referralPartner.findUnique({ where: { code } });
  if (clash) return { error: "That code is already in use." };

  // Optional: link the partner to an existing user account (by email) so they can
  // sign in and see their portal. Silently skipped if no such user.
  const linkEmail = String(formData.get("linkEmail") ?? "").trim().toLowerCase();
  let userId: string | null = null;
  if (linkEmail) {
    const u = await db.user.findUnique({ where: { email: linkEmail }, select: { id: true } });
    if (!u) return { error: `No user account found for ${linkEmail}.` };
    const taken = await db.referralPartner.findUnique({ where: { userId: u.id } });
    if (taken) return { error: "That user is already a partner." };
    userId = u.id;
  }

  const partner = await db.referralPartner.create({
    data: { name, code, contactEmail, commissionRatePct: rate, userId, status: "ACTIVE" },
  });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "partner.create",
      detail: `${partner.name} (${partner.code}) @ ${rate}%`,
    },
  });
  revalidatePath("/admin/partners");
  return { ok: true };
}

// ---------- Update rate / status ----------

export async function adminUpdatePartner(
  id: string,
  patch: { commissionRatePct?: number; status?: string }
): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("billing");
  const partner = await db.referralPartner.findUnique({ where: { id } });
  if (!partner) return { error: "Partner not found." };

  const data: { commissionRatePct?: number; status?: string } = {};
  if (patch.commissionRatePct != null) {
    const rate = clampRate(patch.commissionRatePct);
    if (rate <= 0) return { error: "Commission rate must be greater than 0%." };
    data.commissionRatePct = rate;
  }
  if (patch.status != null) {
    if (patch.status !== "ACTIVE" && patch.status !== "PAUSED") {
      return { error: "Invalid status." };
    }
    data.status = patch.status;
  }
  if (Object.keys(data).length === 0) return { error: "Nothing to update." };

  await db.referralPartner.update({ where: { id }, data });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "partner.update",
      detail: `${partner.code} ${JSON.stringify(data)}`,
    },
  });
  revalidatePath("/admin/partners");
  revalidatePath(`/admin/partners/${id}`);
  return { ok: true };
}

// ---------- Attach / detach a customer ----------

/**
 * Attach a customer (by email) to a partner for life. Enforces the single-partner
 * rule (a customer already attached to a partner cannot be moved — the unique
 * `customerId` also hard-stops it) so attribution is never silently reassigned.
 */
export async function adminAttachCustomer(
  partnerId: string,
  email: string
): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("billing");
  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
  if (!partner) return { error: "Partner not found." };

  const customer = await db.user.findUnique({
    where: { email: email.trim().toLowerCase() },
    select: { id: true },
  });
  if (!customer) return { error: "No customer found with that email." };
  if (partner.userId && partner.userId === customer.id) {
    return { error: "A partner cannot be attached to their own account." };
  }

  const existing = await db.partnerCustomer.findUnique({
    where: { customerId: customer.id },
    include: { partner: { select: { name: true } } },
  });
  if (existing) {
    return existing.partnerId === partnerId
      ? { error: "That customer is already attached to this partner." }
      : { error: `That customer is already attached to ${existing.partner.name}.` };
  }

  await db.partnerCustomer.create({ data: { partnerId, customerId: customer.id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "partner.attach", detail: `${partner.code} <- ${email}` },
  });
  revalidatePath(`/admin/partners/${partnerId}`);
  return { ok: true };
}

/**
 * Detach a customer from a partner. Historical commission rows are LEFT INTACT
 * (they record charges that really happened); only the forward attachment is
 * removed, so no new commission accrues for this customer afterwards.
 */
export async function adminDetachCustomer(
  attachmentId: string
): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("billing");
  const attachment = await db.partnerCustomer.findUnique({ where: { id: attachmentId } });
  if (!attachment) return { error: "Attachment not found." };

  await db.partnerCustomer.delete({ where: { id: attachmentId } });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "partner.detach",
      detail: `${attachment.partnerId} -/- ${attachment.customerId}`,
    },
  });
  revalidatePath(`/admin/partners/${attachment.partnerId}`);
  return { ok: true };
}

// ---------- Settle commission (mark accrued -> paid) ----------

/**
 * Mark all currently-ACCRUED commission for a partner as PAID, stamping `paidAt`.
 * This records a settlement OUTSIDE the wallet (partners are typically paid by
 * bank transfer / invoice), so unlike the affiliate cash-out it moves no wallet
 * balance — it only advances the ledger status. Returns how many rows/cents were
 * settled.
 */
export async function adminSettlePartnerCommission(
  partnerId: string
): Promise<{ error?: string; ok?: boolean; count?: number; cents?: number }> {
  const admin = await requireArea("billing");
  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
  if (!partner) return { error: "Partner not found." };

  const agg = await db.partnerCommission.aggregate({
    where: { partnerId, status: "ACCRUED" },
    _sum: { amountCents: true },
    _count: true,
  });
  const cents = agg._sum.amountCents ?? 0;
  const count = agg._count ?? 0;
  if (count === 0) return { error: "Nothing to settle — no accrued commission." };

  await db.partnerCommission.updateMany({
    where: { partnerId, status: "ACCRUED" },
    data: { status: "PAID", paidAt: new Date() },
  });
  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "partner.settle",
      detail: `${partner.code}: ${count} rows, $${(cents / 100).toFixed(2)}`,
    },
  });
  revalidatePath(`/admin/partners/${partnerId}`);
  revalidatePath("/admin/partners");
  return { ok: true, count, cents };
}

// KOL / Agency partner commission engine.
//
// The peer-referral program (lib/actions-growth.ts maybeRewardReferral +
// User.referralCode/referredById + AffiliatePayout) pays a customer a ONE-TIME
// wallet bonus for referring a friend. THIS module is a separate, additive
// program for agencies / content creators (KOLs): a partner is permanently
// attached to a customer they brought on (PartnerCustomer) and earns a LIFETIME
// percentage on EVERY qualifying charge that customer makes — the initial order
// AND every renewal, across all products — recorded as a PartnerCommission row.
//
// Idempotency: PartnerCommission.invoiceId is UNIQUE, so at most one commission
// row can ever exist per charge. Every accrual path (the inline hooks after an
// order/renewal, and the background reconciliation sweep) funnels through
// `accrueCommissionForInvoice`, which swallows the unique-violation on a
// re-attempt. A partner therefore can never be double-accrued for one charge.

import { db } from "./db";
import type { Invoice, Prisma } from "@prisma/client";

/**
 * Invoice descriptions that are NOT service sales and must never earn commission:
 *  - wallet top-ups (money IN, not a purchase — the service it later funds is its
 *    own invoice and is what earns the commission; accruing on both would double
 *    count). "Wallet top-up" is lib/stripe.ts; "Automatic wallet top-up" is the
 *    auto-recharge in worker/billing.ts (AUTO_RECHARGE_DESC).
 * Refunds/credits are excluded separately by the `amountCents <= 0` guard below.
 */
const NON_COMMISSIONABLE_DESCRIPTIONS = new Set(["Wallet top-up", "Automatic wallet top-up"]);

export type CommissionableInvoice = Pick<
  Invoice,
  "id" | "userId" | "status" | "amountCents" | "taxCents" | "description" | "createdAt"
>;

/**
 * Is this invoice a qualifying charge a partner earns commission on? True for any
 * PAID invoice with a positive total that isn't a wallet top-up. This is the one
 * classifier every accrual path shares.
 */
export function isCommissionableInvoice(inv: CommissionableInvoice): boolean {
  if (inv.status !== "PAID") return false;
  if (inv.amountCents <= 0) return false; // refunds / zero-value docs
  if (NON_COMMISSIONABLE_DESCRIPTIONS.has(inv.description.trim())) return false;
  return true;
}

/** Coarse kind label for the ledger, inferred from the invoice description. */
function inferKind(description: string): "ORDER" | "RENEWAL" | "CHARGE" {
  const d = description.toLowerCase();
  if (d.includes("renewal") || d.startsWith("renew")) return "RENEWAL";
  if (d.startsWith("order:")) return "ORDER";
  return "CHARGE";
}

/**
 * Accrue the partner commission for a single qualifying invoice, IF the invoice's
 * owner is attached to an ACTIVE partner and no commission has been recorded yet.
 *
 * Idempotent and safe to call from anywhere, any number of times:
 *  - not commissionable / no partner attachment / paused partner  -> returns null.
 *  - a commission already exists for the invoice (unique invoiceId) -> returns null
 *    (the create throws P2002, which is swallowed).
 * Commission is computed on the NET (pre-tax) charge = amountCents - taxCents.
 *
 * Never throws for the "expected" cases; unexpected DB errors DO propagate so the
 * caller (which wraps this best-effort) can log them.
 */
export async function accrueCommissionForInvoice(
  inv: CommissionableInvoice
): Promise<{ commissionId: string; amountCents: number } | null> {
  if (!isCommissionableInvoice(inv)) return null;

  const attachment = await db.partnerCustomer.findUnique({
    where: { customerId: inv.userId },
    include: { partner: true },
  });
  if (!attachment) return null;
  const partner = attachment.partner;
  if (partner.status !== "ACTIVE") return null;

  // FUTURE-ONLY attribution: a partner earns only on charges dated at/after the
  // customer was attached to them. Attaching an existing customer therefore never
  // back-bills their prior invoices (no surprise retroactive liability); it starts
  // the lifetime clock from the attachment forward.
  if (inv.createdAt < attachment.createdAt) return null;

  const rate = Number.isFinite(partner.commissionRatePct) ? partner.commissionRatePct : 0;
  if (rate <= 0) return null;

  const baseCents = Math.max(0, inv.amountCents - (inv.taxCents ?? 0));
  if (baseCents <= 0) return null;
  const amountCents = Math.round((baseCents * rate) / 100);
  if (amountCents <= 0) return null;

  try {
    const row = await db.partnerCommission.create({
      data: {
        partnerId: partner.id,
        customerId: inv.userId,
        invoiceId: inv.id,
        baseCents,
        ratePct: rate,
        amountCents,
        kind: inferKind(inv.description),
        status: "ACCRUED",
      },
      select: { id: true, amountCents: true },
    });
    return { commissionId: row.id, amountCents: row.amountCents };
  } catch (e) {
    // Unique violation on invoiceId => another path already accrued this charge.
    // That is the idempotency guarantee working, not an error.
    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") return null;
    throw e;
  }
}

/**
 * Immediate, best-effort accrual for a customer's most recent qualifying charges.
 * Called inline right after a synchronous order/renewal commits so the partner
 * sees the commission attach at once (the sweep would otherwise catch it within a
 * few minutes). Scans the customer's newest PAID invoices, accruing any that lack
 * a commission row. Never throws — logs and moves on.
 */
export async function accrueRecentCommissionsForCustomer(
  customerId: string,
  limit = 5
): Promise<void> {
  try {
    // Fast exit for the overwhelmingly common case: the customer has no partner.
    const attached = await db.partnerCustomer.findUnique({
      where: { customerId },
      select: { id: true },
    });
    if (!attached) return;

    const invoices = await db.invoice.findMany({
      where: { userId: customerId, status: "PAID", partnerCommission: null },
      orderBy: { createdAt: "desc" },
      take: limit,
      select: { id: true, userId: true, status: true, amountCents: true, taxCents: true, description: true, createdAt: true },
    });
    for (const inv of invoices) {
      await accrueCommissionForInvoice(inv);
    }
  } catch (e) {
    console.error("[partner-commission] inline accrual failed for", customerId, e);
  }
}

/**
 * Background reconciliation sweep: accrue commission for every qualifying PAID
 * invoice that doesn't yet have a commission row and whose owner is attached to a
 * partner. This is the DURABLE hook — it covers every charge path uniformly
 * (initial orders, all renewals, upgrades, add-ons, domain/email/hosting/nxcloud
 * renewals) without each charge site needing to know about the partner program,
 * and it self-heals any charge the inline hooks missed. Idempotent.
 *
 * Wired into the billing worker loop (worker/index.ts) alongside billingSweep.
 * `sinceDays` bounds the scan so it stays cheap on each pass; anything older than
 * that has long since been accrued on a prior sweep.
 */
export async function reconcilePartnerCommissions(
  opts: { sinceDays?: number; limit?: number } = {}
): Promise<{ scanned: number; accrued: number }> {
  const sinceDays = opts.sinceDays ?? 45;
  const limit = opts.limit ?? 500;
  const since = new Date(Date.now() - sinceDays * 24 * 60 * 60_000);

  // Only invoices belonging to an attached customer are candidates. We join through
  // PartnerCustomer so partner-less customers (the vast majority) are never scanned.
  const invoices = await db.invoice.findMany({
    where: {
      status: "PAID",
      partnerCommission: null,
      createdAt: { gte: since },
      user: { partnerAttachment: { isNot: null } },
    },
    orderBy: { createdAt: "asc" },
    take: limit,
    select: { id: true, userId: true, status: true, amountCents: true, taxCents: true, description: true, createdAt: true },
  });

  let accrued = 0;
  for (const inv of invoices) {
    try {
      const res = await accrueCommissionForInvoice(inv);
      if (res) accrued++;
    } catch (e) {
      // One bad invoice must never abort the sweep.
      console.error("[partner-commission] sweep accrual failed for invoice", inv.id, e);
    }
  }
  return { scanned: invoices.length, accrued };
}

// ---------- Partner-facing summary ----------

export type PartnerSummary = {
  partnerId: string;
  name: string;
  code: string;
  commissionRatePct: number;
  status: string;
  customerCount: number;
  /** Lifetime commission ever accrued (ACCRUED + PAID), in cents. */
  lifetimeCents: number;
  /** Accrued but not yet paid out, in cents. */
  outstandingCents: number;
  /** Already paid out, in cents. */
  paidCents: number;
};

/**
 * Roll up a partner's standing: attached-customer count and commission totals by
 * status. Used by both the partner portal and the admin views.
 */
export async function computePartnerSummary(partnerId: string): Promise<PartnerSummary | null> {
  const partner = await db.referralPartner.findUnique({ where: { id: partnerId } });
  if (!partner) return null;

  const [customerCount, accruedAgg, paidAgg] = await Promise.all([
    db.partnerCustomer.count({ where: { partnerId } }),
    db.partnerCommission.aggregate({
      where: { partnerId, status: "ACCRUED" },
      _sum: { amountCents: true },
    }),
    db.partnerCommission.aggregate({
      where: { partnerId, status: "PAID" },
      _sum: { amountCents: true },
    }),
  ]);

  const outstandingCents = accruedAgg._sum.amountCents ?? 0;
  const paidCents = paidAgg._sum.amountCents ?? 0;
  return {
    partnerId: partner.id,
    name: partner.name,
    code: partner.code,
    commissionRatePct: partner.commissionRatePct,
    status: partner.status,
    customerCount,
    lifetimeCents: outstandingCents + paidCents,
    outstandingCents,
    paidCents,
  };
}

/**
 * Attach a customer to the partner whose `code` matches, for life. No-op if the
 * code doesn't map to an ACTIVE partner, or the customer is already attached to a
 * partner (attachment is permanent and single — the unique `customerId` also hard-
 * enforces this). Best-effort: returns whether an attachment was made. Intended to
 * be called from the registration flow when a `?ref=` code is a partner code.
 */
export async function attachCustomerToPartnerByCode(
  customerId: string,
  rawCode: string | null | undefined
): Promise<boolean> {
  // Partner codes are stored upper-cased (see lib/actions-partner.ts normalizeCode).
  const code = (rawCode ?? "").trim().toUpperCase();
  if (!code) return false;
  try {
    const partner = await db.referralPartner.findUnique({ where: { code } });
    if (!partner || partner.status !== "ACTIVE") return false;
    // A partner cannot self-attach (would earn commission on their own spend).
    if (partner.userId && partner.userId === customerId) return false;
    const existing = await db.partnerCustomer.findUnique({ where: { customerId } });
    if (existing) return false;
    await db.partnerCustomer.create({ data: { partnerId: partner.id, customerId } });
    return true;
  } catch (e) {
    // Unique race (two concurrent attaches) or transient error — never fatal to
    // the caller (registration/order must still succeed).
    if ((e as Prisma.PrismaClientKnownRequestError)?.code === "P2002") return false;
    console.error("[partner-commission] attach-by-code failed for", customerId, e);
    return false;
  }
}
