  });
}
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { authenticateApiToken, tokenHasScope } from "@/lib/api-auth";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const dynamic = "force-dynamic";

/**
 * GET /api/v1/servers
 * Bearer-token authenticated. Returns the caller's servers.
 *
 *   Authorization: Bearer nxe_<prefix>_<random>
 */
export async function GET(req: Request) {
  const auth = await authenticateApiToken(req);
  if (!auth.ok) {
    return NextResponse.json({ error: auth.error }, { status: auth.status, headers: NO_STORE_HEADERS });
  }

  // Enforce read scope. Legacy tokens (no scopes recorded) are READ-ONLY — they
  // satisfy this check and nothing that mutates. See `tokenHasScope` in
  // lib/api-auth.ts; a mutating endpoint must use `authorizeApiRequest`.
  if (!tokenHasScope(auth, "servers:read")) {
    return NextResponse.json(
      { error: "Token missing required scope: servers:read" },
      { status: 403, headers: NO_STORE_HEADERS }
    );
  }

  const servers = await db.server.findMany({
    where: { userId: auth.user.id },
    orderBy: { createdAt: "desc" },
    select: { id: true, name: true, status: true, ipAddress: true },
  });

  // Per-account inventory (names + IP addresses). The URL is identical for every
  // token holder, so a shared cache keyed on the URL alone would serve one
  // customer's server list to the next — `Authorization` is a request header and
  // does not vary the cache key on its own. `private` is the control that matters.
  return NextResponse.json(
    {
      servers: servers.map((s) => ({
        id: s.id,
        name: s.name,
        status: s.status,
        ip: s.ipAddress,
      })),
    },
    { headers: NO_STORE_HEADERS }
  );
}

import { db } from "@/lib/db";
import { logEvent } from "@/lib/log";

/**
 * The Nxeon Cipher — a 4-gate riddle promotion at /riddle.
 *
 * ONE global first-solver wins a $100 account credit (valid toward a single VPS).
 * "First wins" is made atomic by the `RiddleWinner.singleton` unique column: the
 * award runs inside a transaction that INSERTs the winner row, and the second
 * concurrent correct answer loses on the unique-index violation.
 *
 * The final answer lives here as a NORMALISED constant (server-only — never shipped
 * to the browser, never checked client-side). An operator can override it without a
 * deploy via the `riddle_answer` Setting.
 */
export const RIDDLE_AWARD_CENTS = 10_000; // $100.00
export const RIDDLE_PRIZE_DESC = "Riddle prize — $100 credit (valid toward one VPS)";

// Fallback answer if the Setting is unset. OBSIDIAN-HELIX-7334 (see the sigil).
const DEFAULT_ANSWER_NORM = "OBSIDIANHELIX7334";

// Per-user throttle so the (astronomically large) answer space can't be brute-forced
// and the attempt log can't be flooded.
const MAX_ATTEMPTS_PER_HOUR = 15;

/** Uppercase + strip everything but A–Z/0–9 so punctuation/case/spacing never matter. */
export function normalizeAnswer(raw: string): string {
  return raw.toUpperCase().replace(/[^A-Z0-9]/g, "");
}

async function correctAnswerNorm(): Promise<string> {
  const s = await db.setting.findUnique({ where: { key: "riddle_answer" } }).catch(() => null);
  const v = s?.value ? normalizeAnswer(s.value) : "";
  return v || DEFAULT_ANSWER_NORM;
}

export type RiddleState = {
  solved: boolean;
  wonByMe: boolean;
  winnerAt: Date | null;
};

export async function getRiddleState(userId: string | null): Promise<RiddleState> {
  const winner = await db.riddleWinner.findFirst().catch(() => null);
  return {
    solved: !!winner,
    wonByMe: !!winner && !!userId && winner.userId === userId,
    winnerAt: winner?.createdAt ?? null,
  };
}

export type SubmitResult =
  | { status: "correct_won" }
  | { status: "correct_but_closed" } // right answer, but someone else already won
  | { status: "already_won" } // this user is already the winner
  | { status: "closed" } // riddle solved by someone else; wrong/late answer
  | { status: "wrong" }
  | { status: "rate_limited"; retryMinutes: number };

/**
 * Submit an answer for `userId`. Logs every attempt, throttles per user, and on the
 * first correct answer atomically records the winner + credits $100.
 */
export async function submitRiddleAnswer(userId: string, raw: string): Promise<SubmitResult> {
  // 1) Throttle.
  const since = new Date(Date.now() - 60 * 60 * 1000);
  const recent = await db.riddleAttempt.count({ where: { userId, createdAt: { gte: since } } });
  if (recent >= MAX_ATTEMPTS_PER_HOUR) {
    return { status: "rate_limited", retryMinutes: 60 };
  }

  const guess = normalizeAnswer(raw);
  const answer = await correctAnswerNorm();
  const isCorrect = guess.length > 0 && guess === answer;

  // 2) Always log the attempt (audit + anti-abuse).
  await db.riddleAttempt.create({ data: { userId, answer: guess.slice(0, 120), correct: isCorrect } }).catch(() => {});

  if (!isCorrect) {
    // If it's already solved, tell them so instead of an endless "wrong".
    const w = await db.riddleWinner.findFirst().catch(() => null);
    return w ? { status: "closed" } : { status: "wrong" };
  }

  // 3) Correct. Am I already the winner?
  const existing = await db.riddleWinner.findFirst().catch(() => null);
  if (existing) {
    return existing.userId === userId ? { status: "already_won" } : { status: "correct_but_closed" };
  }

  // 4) First correct answer — award atomically. The singleton unique column means
  //    only ONE winner row can ever exist; a racing second winner hits P2002.
  try {
    await db.$transaction(async (tx) => {
      await tx.riddleWinner.create({ data: { userId, answer: guess.slice(0, 120), awardCents: RIDDLE_AWARD_CENTS } });
      await tx.user.update({ where: { id: userId }, data: { balanceCents: { increment: RIDDLE_AWARD_CENTS } } });
      await tx.walletTransaction.create({ data: { userId, amountCents: RIDDLE_AWARD_CENTS, description: RIDDLE_PRIZE_DESC } });
    });
    await logEvent("info", "riddle.solved", { userId, awardCents: RIDDLE_AWARD_CENTS });
    return { status: "correct_won" };
  } catch (e: unknown) {
    // Unique violation => a concurrent submission won the race a moment earlier.
    const code = (e as { code?: string })?.code;
    if (code === "P2002") return { status: "correct_but_closed" };
    throw e;
  }
}
"use server";

import { randomInt } from "crypto";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { getSettingBool } from "./settings";
import type { User } from "@prisma/client";

/** Alphabet for generated gift codes — no ambiguous chars (0/O, 1/I). */
const ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

function randomSegment(len: number): string {
  let s = "";
  for (let i = 0; i < len; i++) s += ALPHABET[randomInt(ALPHABET.length)];
  return s;
}

/** Generate a code like `NXEON-XXXX-XXXX`. */
function generateGiftCode(): string {
  return `NXEON-${randomSegment(4)}-${randomSegment(4)}`;
}

/** Allocate a code that is unique in the DB (retry on the rare clash). */
async function uniqueGiftCode(): Promise<string> {
  for (let i = 0; i < 8; i++) {
    const code = generateGiftCode();
    const clash = await db.giftCode.findUnique({ where: { code } });
    if (!clash) return code;
  }
  // Extremely unlikely; add a third segment for extra entropy.
  return `${generateGiftCode()}-${randomSegment(4)}`;
}

// ---------- Admin: create ----------

const createSchema = z.object({
  amount: z.coerce.number().positive().max(10000),
  note: z.string().max(200).optional(),
  count: z.coerce.number().int().min(1).max(100),
});

/**
 * Create one or more gift/credit codes. `amount` is dollars (converted to
 * cents), `count` bulk-generates N codes with the same amount/note.
 */
export async function adminCreateGiftCodes(
  prev: any,
  formData: FormData
): Promise<{ error?: string; ok?: boolean; codes?: string[] }> {
  const admin = await requireArea("billing");
  const rawNote = String(formData.get("note") ?? "").trim();
  const parsed = createSchema.safeParse({
    amount: formData.get("amount"),
    note: rawNote === "" ? undefined : rawNote,
    count: formData.get("count") || 1,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid gift code details." };
  }
  const { amount, note, count } = parsed.data;
  const amountCents = Math.round(amount * 100);
  if (amountCents < 1) return { error: "Amount must be at least $0.01." };

  const codes: string[] = [];
  for (let i = 0; i < count; i++) {
    const code = await uniqueGiftCode();
    await db.giftCode.create({
      data: { code, amountCents, note: note ?? null },
    });
    codes.push(code);
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "admin.giftcode_create",
      detail: `${count} x $${amount.toFixed(2)}`,
    },
  });
  revalidatePath("/admin/gift-codes");
  return { ok: true, codes };
}

// ---------- Admin: delete (unredeemed only) ----------

export async function adminDeleteGiftCode(id: string): Promise<void> {
  const admin = await requireArea("billing");
  const gift = await db.giftCode.findUnique({ where: { id } });
  if (!gift) return;
  if (gift.redeemedById) return; // never delete a redeemed code
  await db.giftCode.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.giftcode_delete", detail: gift.code },
  });
  revalidatePath("/admin/gift-codes");
}

// ---------- Customer: redeem ----------

/**
 * Redeem a gift code into the current user's wallet. Race-safe: the claim is an
 * `updateMany` guarded by `redeemedById: null` inside a transaction, so two
 * concurrent redemptions of the same code can only ever succeed once.
 */
export async function redeemGiftCode(
  rawCode: string
): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
  const user = await requireUser();
  const code = String(rawCode ?? "").trim().toUpperCase();
  if (!code) return { error: "Enter a gift code." };

  const gift = await db.giftCode.findUnique({ where: { code } });
  // Not a single-use gift code? It might be a multi-use CREDIT_CENTS coupon
  // (e.g. a "free month" promo) — redeem that for wallet credit, no purchase.
  if (!gift) return redeemCreditCoupon(user, code);
  if (gift.redeemedById) return { error: "This code has already been redeemed." };

  const result = await db.$transaction(async (tx) => {
    // Atomic claim: only succeeds if the code is still unredeemed.
    const claim = await tx.giftCode.updateMany({
      where: { id: gift.id, redeemedById: null },
      data: { redeemedById: user.id, redeemedAt: new Date() },
    });
    if (claim.count !== 1) return { error: "This code has already been redeemed." };

    await tx.user.update({
      where: { id: user.id },
      data: { balanceCents: { increment: gift.amountCents } },
    });
    await tx.walletTransaction.create({
      data: {
        userId: user.id,
        amountCents: gift.amountCents,
        description: `Gift code redeemed (${gift.code})`,
      },
    });
    return { ok: true, amountCents: gift.amountCents };
  });

  if (result.ok) {
    revalidatePath("/dashboard/billing");
  }
  return result;
}

/**
 * Redeem a multi-use CREDIT_CENTS coupon (e.g. a "free month" promo) straight
 * into the wallet — no top-up/purchase required. Enforces enabled / active /
 * expiry / per-coupon `maxRedemptions` / one-per-user / first-time-only, all
 * race-safe: the limit is an atomic conditional increment, and the per-user cap
 * is the `@@unique([couponId,userId])` on CouponRedemption (a concurrent
 * double-redeem throws and rolls the whole transaction back).
 */
async function redeemCreditCoupon(
  user: User,
  code: string
): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
  if (!(await getSettingBool("coupons_enabled", true))) {
    return { error: "Promo codes are currently disabled." };
  }
  const coupon = await db.coupon.findUnique({ where: { code } });
  if (!coupon || !coupon.active) {
    return { error: "That code isn't valid. Check for typos and try again." };
  }
  if (coupon.kind !== "CREDIT_CENTS") {
    // PERCENT / FIXED_CENTS are discounts on a top-up, entered when adding funds.
    return { error: "This code is a discount on a top-up — enter it when you add funds." };
  }
  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
    return { error: "This code has expired." };
  }
  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
    return { error: "This code has reached its redemption limit." };
  }
  const already = await db.couponRedemption.findUnique({
    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
  });
  if (already) return { error: "You've already used this code." };
  if (coupon.firstTimeOnly) {
    const priorCredits = await db.walletTransaction.count({
      where: { userId: user.id, amountCents: { gt: 0 } },
    });
    if (priorCredits > 0) return { error: "This code is for first-time customers only." };
  }

  const result = await db
    .$transaction(async (tx) => {
      // Atomic limit claim — only proceeds while under the cap (skipped if uncapped).
      if (coupon.maxRedemptions !== null) {
        const claim = await tx.coupon.updateMany({
          where: { id: coupon.id, timesRedeemed: { lt: coupon.maxRedemptions } },
          data: { timesRedeemed: { increment: 1 } },
        });
        if (claim.count !== 1) return { error: "This code has reached its redemption limit." };
      } else {
        await tx.coupon.update({ where: { id: coupon.id }, data: { timesRedeemed: { increment: 1 } } });
      }
      // One-per-user via the unique constraint (a race throws → full rollback).
      await tx.couponRedemption.create({
        data: { couponId: coupon.id, userId: user.id, amountCents: coupon.value, context: "free-credit" },
      });
      await tx.user.update({
        where: { id: user.id },
        data: { balanceCents: { increment: coupon.value } },
      });
      await tx.walletTransaction.create({
        data: { userId: user.id, amountCents: coupon.value, description: `Promo code redeemed (${coupon.code})` },
      });
      return { ok: true, amountCents: coupon.value };
    })
    .catch(() => ({ error: "You've already used this code." }) as { error: string });

  if ("ok" in result && result.ok) revalidatePath("/dashboard/billing");
  return result;
}
