  currentProjectId: string | null;
  projects: { id: string; name: string; color: string }[];
}) {
  const [pending, start] = useTransition();
  const [value, setValue] = useState(currentProjectId ?? "");

  if (projects.length === 0) {
    return (
      <p className="text-sm text-slate-400">
        No projects yet.{" "}
        <Link href="/dashboard/projects" className="text-brand-300 hover:underline">
          Create one
        </Link>{" "}
        to group your servers.
      </p>
    );
  }

  return (
    <div className="flex items-center gap-3">
      <select
        className="input max-w-xs"
        value={value}
        disabled={pending}
        onChange={(e) => {
          const v = e.target.value;
          setValue(v);
          start(() => assignServerProject(serverId, v === "" ? null : v));
        }}
      >
        <option value="">— No project —</option>
        {projects.map((p) => (
          <option key={p.id} value={p.id}>
            {p.name}
          </option>
        ))}
      </select>
      {pending && <span className="text-xs text-slate-500">Saving…</span>}
    </div>
  );
}
