import { useActionState, useTransition } from "react";
import { createProject, deleteProject } from "@/lib/actions-account";

export function CreateProjectForm() {
  const [state, action, pending] = useActionState(createProject, {});
  return (
    <form action={action} className="flex flex-wrap items-end gap-3">
      <div>
        <label className="label">Project name</label>
        <input className="input w-56" name="name" required maxLength={50} placeholder="Production" />
      </div>
      <div>
        <label className="label">Color</label>
        <input
          className="h-[42px] w-14 cursor-pointer rounded-xl border border-white/10 bg-navy-900/80 p-1"
          type="color"
          name="color"
          defaultValue="#6f47f5"
        />
      </div>
      <button className="btn-primary" disabled={pending}>
        {pending ? "Creating…" : "Create project"}
      </button>
      {state?.error && <p className="w-full text-sm text-red-400">{state.error}</p>}
    </form>
  );
}

export function DeleteProjectButton({
  projectId,
  serverCount,
}: {
  projectId: string;
  serverCount: number;
}) {
  const [pending, start] = useTransition();
  if (serverCount > 0) {
    return (
      <span
        className="text-xs text-slate-500"
        title="Move or delete the servers in this project first."
      >
        {serverCount} server{serverCount === 1 ? "" : "s"} — cannot delete
      </span>
    );
  }
  return (
    <button
      className="btn-danger px-3 py-1 text-xs"
      disabled={pending}
      onClick={() => {
        if (window.confirm("Delete this empty project?")) start(() => deleteProject(projectId));
      }}
    >
      {pending ? "…" : "Delete"}
    </button>
  );
}

